260	\begin{lemma}[Consistency versus closeness; Fact 4.13 in \cite{Natarajan2018NEEXP}]\label{fact:agreement}
261		\lean{MIPStarRE.QPBT.opFamilyDistSq_le_two_mul_consistencyDefect, MIPStarRE.QPBT.consistencyDefect_le_opFamilyDistSq_of_projective}
262		\leanok
