628			Let $f : \alpha \to \mathbb{R}$ be a function on a finite index set $\alpha$ with
629			$|\alpha| = r$, and let $L \subseteq \alpha$ with $|L| = d$ and $d < r$. Write
630			$S = L^\complement$ and assume $f(s) \leq f(l)$ for every $s \in S$ and $l \in L$.
631			Then the pairwise double-counting inequality
632			\[
633				|L|\, \sum_{s \in S} f(s) \leq |S|\, \sum_{l \in L} f(l)
634			\]
635			holds, and hence also
636			\[
637				r\, \sum_{s \in S} f(s) \leq |S|\, \sum_{x \in \alpha} f(x).
638			\]
639			If in addition $r \leq (1+2\sqrt{\zeta})\,d$, $\sum_{x \in \alpha} f(x) \leq
640			1 + 2\sqrt{\zeta}$, and $0 \leq \zeta \leq 1/4$, then
641			\[
642				\sum_{s \in S} f(s) \leq 4\sqrt{\zeta}.
643			\]
644		\end{lemma}
645		\begin{proof}
646			\leanok
647			Choose $L$ to be a set of $d$ indices on which the sum of $f$ is maximal. If some $s \in S$ and $l \in L$ satisfied $f(l) < f(s)$, replacing $l$ by $s$ would increase this sum, so every small index is bounded by every large index. Summing the inequalities $f(s) \leq f(l)$ over all pairs $(s,l) \in S \times L$ gives
648			\[
649				|L|\sum_{s \in S} f(s) \leq |S|\sum_{l \in L} f(l).
650			\]
651			Since $\alpha$ is the disjoint union of $L$ and $S$, adding $|S|\sum_{s \in S} f(s)$ to both sides yields
652			\[
653				r\sum_{s \in S} f(s) \leq |S|\sum_{x \in \alpha} f(x).
654			\]
655			The hypotheses $|L|=d$ and $r \leq (1+2\sqrt{\zeta})d$ imply $|S|/r \leq 2\sqrt{\zeta}$. Dividing by $r$ and using $\sum_{x \in \alpha} f(x) \leq 1+2\sqrt{\zeta}$ gives
656			\[
657				\sum_{s \in S} f(s) \leq 2\sqrt{\zeta}(1+2\sqrt{\zeta}).
658			\]
659			Finally, $\zeta \leq 1/4$ implies $\sqrt{\zeta} \leq 1/2$, and hence $2\sqrt{\zeta}(1+2\sqrt{\zeta}) \leq 4\sqrt{\zeta}$.
